-- fr 공식 계정(pinwith_fr)·예시 계정·예시 리스트 4개. 먼저 seed_lang_loader.sql을 실행해 둘 것.
select private.seed_lang_examples('fr', 'fr', $doc${"official":{"display_name":"PinWith officiel","bio":"Des listes de lieux préparées par l'équipe PinWith pour vous inspirer."},"samples":[{"display_name":"Utilisateur exemple 1","bio":"Compte d'exemple créé par PinWith pour montrer comment des amis préparent un voyage ensemble."},{"display_name":"Utilisateur exemple 2","bio":"Compte d'exemple créé par PinWith pour montrer comment des amis préparent un voyage ensemble."},{"display_name":"Utilisateur exemple 3","bio":"Compte d'exemple créé par PinWith pour montrer comment des amis préparent un voyage ensemble."}],"lists":[{"role":"plain","owner":"official","slug":"paris-premiere-visite","kind":"collection","title":"Paris : l'essentiel pour une première visite","desc":"Les incontournables de Paris regroupés par quartier, pour organiser vos journées sans perdre de temps dans le métro.","themes":["Paris","incontournables","monuments","musées","balade"],"sections":[{"name":"Île de la Cité et Marais","by":"official","items":[{"place_id":"ChIJATr1n-Fx5kcRjQb6q6cdQDY","title":"Notre-Dame de Paris","memo":"L'entrée est gratuite mais la file peut être longue : réservez un créneau en ligne ou venez dès l'ouverture.","tags":["cathédrale","gratuit"],"lat":48.852968,"lng":2.349902},{"place_id":"ChIJR3122B9u5kcRaCck3PlB9DM","title":"Sainte-Chapelle","memo":"Visitez-la par une journée ensoleillée : les vitraux de la chapelle haute sont bien plus éclatants. Contrôle de sécurité du Palais de justice à prévoir.","tags":["vitraux","réservation"],"lat":48.855375,"lng":2.344961},{"place_id":"ChIJUeiI4P9x5kcRqEwHl6V32GQ","title":"Place des Vosges","memo":"La plus ancienne place de Paris : faites une pause sur les pelouses, puis flânez sous les arcades et dans les rues du Marais.","tags":["Marais","pause"],"lat":48.855611,"lng":2.365527}]},{"name":"Rive droite et rive gauche","by":"official","items":[{"place_id":"ChIJD3uTd9hx5kcR1IQvGfr8dbk","title":"Le Louvre","memo":"Réservez votre horaire à l'avance et ciblez deux ou trois départements plutôt que de tout vouloir voir. La nocturne est souvent plus calme.","tags":["musée","réservation"],"lat":48.860611,"lng":2.337644},{"place_id":"ChIJG5Qwtitu5kcR2CNEsYy9cdA","title":"Musée d'Orsay","memo":"Montez directement au 5e étage pour les impressionnistes et la vue à travers l'horloge géante, avant l'arrivée des groupes.","tags":["impressionnisme","musée"],"lat":48.859961,"lng":2.326561},{"place_id":"ChIJe2jeNttx5kcRi_mJsGHdkQc","title":"Jardin du Luxembourg","memo":"Prenez une des chaises vertes près du grand bassin : c'est la pause idéale entre Saint-Germain et le Quartier latin.","tags":["jardin","gratuit"],"lat":48.846614,"lng":2.336331}]},{"name":"Autour de la tour Eiffel","by":"official","items":[{"place_id":"ChIJpSFnZvtv5kcRlSMne7c0v40","title":"Trocadéro","memo":"Le meilleur point de vue pour photographier la tour Eiffel ; venez tôt le matin pour éviter la foule sur l'esplanade.","tags":["vue","photo"],"lat":48.862798,"lng":2.287604},{"place_id":"ChIJLU7jZClu5kcR4PcOOO6p3I0","title":"Tour Eiffel","memo":"Achetez vos billets sur le site officiel bien en avance. À la nuit tombée, la tour scintille quelques minutes au début de chaque heure.","tags":["monument","soirée"],"lat":48.85837,"lng":2.294481},{"place_id":"ChIJU-XFaSdw5kcReNgoNaOVGe8","title":"Rue Cler","memo":"Rue commerçante piétonne à deux pas de la tour : fromager, boulanger et primeurs pour composer un pique-nique au Champ-de-Mars.","tags":["marché","pique-nique"],"lat":48.856669,"lng":2.306326}]},{"name":"Montmartre","by":"official","items":[{"place_id":"ChIJ442GNENu5kcRGYUrvgqHw88","title":"Sacré-Cœur","memo":"Prenez le funiculaire pour éviter les escaliers, puis redescendez à pied par les petites rues de la Butte au coucher du soleil.","tags":["vue","Montmartre"],"lat":48.886705,"lng":2.343104}]}],"comments":[]},{"role":"creator","owner":"official","slug":"vlog-cote-d-azur-nice-eze","kind":"course","title":"[Vlog] Côte d'Azur : de Nice à Èze, en route vers Monaco","desc":"L'itinéraire de mon vlog sur la Riviera : une journée entre la promenade niçoise, la Moyenne Corniche et le village perché d'Èze, avec mes astuces de tournage. Monaco n'est qu'à quelques minutes de train depuis Èze-sur-Mer pour prolonger la journée.","themes":["vlog","Côte d'Azur","Nice","Èze","photo"],"sections":[{"name":"Matin à Nice","by":"official","items":[{"place_id":"ChIJt5FL9EvRzRIRWrjgb58PTk8","title":"Promenade des Anglais","memo":"Dans la vidéo, j'ai tourné le plan d'ouverture au lever du soleil : la lumière rase sur la Baie des Anges et presque personne sur la promenade.","tags":["lever de soleil","bord de mer"],"lat":43.678313,"lng":7.229842},{"place_id":"ChIJt4AL5qPazRIR68WQ5MDQkNQ","title":"Promenade du Paillon","memo":"Le miroir d'eau donne des reflets superbes pour un plan au ras du sol. Attention, les jets d'eau se déclenchent sans prévenir, protégez votre caméra !","tags":["miroir d'eau","parc"],"lat":43.697441,"lng":7.271463}]},{"name":"La route des corniches","by":"official","items":[{"place_id":"ChIJSfTA4KPEzRIReTu6yp90fgI","title":"Moyenne Corniche","memo":"La route la plus cinématographique de la côte : arrêtez-vous uniquement sur les belvédères aménagés pour filmer la mer en contrebas.","tags":["route panoramique","belvédères"],"lat":43.72318,"lng":7.34599}]},{"name":"Èze, le village perché","by":"official","items":[{"place_id":"ChIJpW9RQt_DzRIRvNGD5b17M-o","title":"Village d'Èze","memo":"Arrivez avant 10 h : les ruelles médiévales sont vides et parfaites pour des plans en marchant. Prévoyez de bonnes chaussures, ça grimpe.","tags":["village médiéval","matin"],"lat":43.727786,"lng":7.361707},{"place_id":"ChIJL9RBEGbDzRIRCZoqea0hC1A","title":"Jardin exotique d'Èze","memo":"Au sommet du village, le panorama sur la mer est le plus beau plan de mon vlog. Fin d'après-midi pour une lumière dorée.","tags":["panorama","jardin"],"lat":43.728302,"lng":7.361226},{"place_id":"ChIJ4yYaEl3DzRIR9LgmWJM_-5Y","title":"Chemin de Nietzsche","memo":"Descente d'environ une heure jusqu'à Èze-sur-Mer : faites-la dans ce sens, avec de l'eau, et évitez les heures les plus chaudes l'été.","tags":["randonnée","sentier"],"lat":43.72444,"lng":7.360496},{"place_id":"ChIJX2qLTwDDzRIR02ClJof2Cro","title":"Plage d'Èze-sur-Mer","memo":"Plage de galets au pied du sentier, idéale pour la séquence de fin au coucher du soleil. La gare est juste à côté pour filer vers Monaco ou rentrer à Nice.","tags":["plage","coucher de soleil"],"lat":43.721776,"lng":7.357801}]}],"comments":[]},{"role":"friends","owner":"ex1","slug":"lisbonne-long-week-end-entre-amis","kind":"collection","title":"Lisbonne : long week-end entre amis","desc":"Trois amis, trois envies, un week-end prolongé à Lisbonne. Chacun a ajouté sa section ; le programme final est dans les commentaires de la Praça do Comércio.","themes":["Lisbonne","entre amis","week-end","Portugal"],"sections":[{"name":"Les envies d'ex1 : Belém","by":"ex1","items":[{"place_id":"ChIJS5zCw0LLHg0RP1FSz63cAjA","title":"Tour de Belém","memo":"Symbole de Lisbonne au bord du Tage ; la file d'attente pour monter est longue, la vue de l'extérieur suffit largement.","tags":["monument","Belém"],"lat":38.691584,"lng":-9.215977},{"place_id":"ChIJw9fPzUPLHg0R2HGx1HnC7Eo","title":"Phare de Belém","memo":"Petit phare à quelques pas de la tour, sympa pour une photo de groupe le long du fleuve.","tags":["photo","bord du Tage"],"lat":38.693086,"lng":-9.208986}]},{"name":"Les envies d'ex2 : Alfama","by":"ex2","items":[{"place_id":"ChIJx-Rwl4QzGQ0RaSfN7SE7IEE","title":"Miradouro de Santa Luzia","memo":"Belvédère avec azulejos et vue sur les toits d'Alfama ; le tram 28 s'arrête juste à côté.","tags":["vue","azulejos"],"lat":38.711696,"lng":-9.130197},{"place_id":"ChIJk-u706A1GQ0RDFz40CSEuSo","title":"Largo do Chafariz de Dentro","memo":"Petite place au bas d'Alfama, point de départ idéal pour se perdre dans les ruelles et trouver un bar à fado le soir.","tags":["fado","ruelles"],"lat":38.711244,"lng":-9.128051},{"place_id":"ChIJbyCqvM8zGQ0R8NBAZs_9Fcw","title":"Feira da Ladra","memo":"Le marché aux puces de Lisbonne, seulement certains jours de la semaine : vérifiez avant d'y aller.","tags":["brocante","marché"],"lat":38.715248,"lng":-9.126207}]},{"name":"Les envies d'ex3 : Baixa et bonne bouffe","by":"ex3","items":[{"place_id":"ChIJY0ulMHo0GQ0RROAoa18vUzA","title":"Praça do Comércio","memo":"Immense place ouverte sur le Tage, parfaite pour un premier rendez-vous et pour partir en tram vers Belém.","tags":["place","rendez-vous"],"lat":38.707283,"lng":-9.136361},{"place_id":"ChIJVZYBfIczGQ0RFFaStJaOGCY","title":"Marché de la Baixa","memo":"Stands de produits portugais et de petits plats sur la Praça da Figueira ; bien pour goûter sans se ruiner.","tags":["street food","Baixa"],"lat":38.713579,"lng":-9.137691},{"place_id":"ChIJdWBeWYc0GQ0RktxySU7hjxM","title":"Time Out Market","memo":"Halle gourmande à Cais do Sodré : beaucoup de choix pour un groupe, mais trouver une table à trois aux heures de pointe demande de la patience.","tags":["food court","Cais do Sodré"],"lat":38.707061,"lng":-9.145669}]}],"comments":[{"place_id":"ChIJS5zCw0LLHg0RP1FSz63cAjA","by":"ex1","body":"Je tiens vraiment à Belém ! On y va le samedi matin ? Le tram 15 part de la Praça do Comércio.","replies":[{"by":"ex2","body":"OK, mais tôt alors, sinon c'est bondé. Et on goûte les pastéis de nata du coin au passage 😋"},{"by":"ex3","body":"Ça marche. On ne monte pas dans la tour par contre, trop d'attente, on fait juste les photos dehors."}]},{"place_id":"ChIJbyCqvM8zGQ0R8NBAZs_9Fcw","by":"ex2","body":"La Feira da Ladra n'ouvre que certains jours, il faut caler Alfama sur un de ces jours-là.","replies":[{"by":"ex1","body":"J'ai vérifié, ça tombe le samedi : Belém le matin, Alfama l'après-midi, ça se fait."}]},{"place_id":"ChIJx-Rwl4QzGQ0RaSfN7SE7IEE","by":"ex3","body":"Le tram 28 est toujours blindé. On monte à pied jusqu'au miradouro ?","replies":[{"by":"ex2","body":"Ça grimpe pas mal mais c'est faisable, une vingtaine de minutes avec des pauses. On prend le tram seulement s'il pleut."},{"by":"ex1","body":"Va pour la marche, et on garde le coucher de soleil pour ici."}]},{"place_id":"ChIJdWBeWYc0GQ0RktxySU7hjxM","by":"ex3","body":"Pour le budget, je propose Time Out Market un soir : chacun prend ce qu'il veut, pas de prise de tête.","replies":[{"by":"ex1","body":"Bonne idée, mais on évite 20 h, c'est la cohue. Vers 19 h ?"},{"by":"ex2","body":"Et le dimanche midi on teste le marché de la Baixa, ça coûtera moins cher."}]},{"place_id":"ChIJY0ulMHo0GQ0RROAoa18vUzA","by":"ex1","body":"Programme final 🎉 Vendredi soir : arrivée, rendez-vous Praça do Comércio puis dîner au Time Out Market vers 19 h. Samedi : tram 15 pour Belém le matin, puis Alfama l'après-midi (Feira da Ladra, montée à pied au Miradouro de Santa Luzia pour le coucher de soleil, fado près du Largo do Chafariz de Dentro). Dimanche : Baixa tranquille et déjeuner au marché de la Baixa avant le départ.","replies":[{"by":"ex2","body":"Parfait ! Je réserve le bar à fado pour samedi soir."},{"by":"ex3","body":"Validé. Je regarde la météo la veille, et s'il pleut on inverse samedi et dimanche."}]}]},{"role":"food","owner":"official","slug":"lyon-bouchons-et-halles","kind":"collection","title":"Lyon : bouchons et Halles Paul Bocuse","desc":"Notre sélection de bouchons lyonnais et de comptoirs des Halles pour manger comme un vrai gone, de la Presqu'île à la Part-Dieu.","themes":["Lyon","bouchon","gastronomie","Halles","cuisine lyonnaise"],"sections":[{"name":"Bouchons de la Presqu'île","by":"official","items":[{"place_id":"ChIJzWkz-f7q9EcRk2Ilt4hYnCs","title":"Chez Paul","memo":"Bouchon à l'ancienne près des Terreaux, ambiance nappes à carreaux ; réservez, surtout le week-end.","tags":["bouchon","traditionnel"],"lat":45.766771,"lng":4.832623},{"place_id":"ChIJcWGBffjq9EcRS5caI8cccUQ","title":"Le Bouchon des Cordeliers","memo":"Idéal pour découvrir les classiques : quenelle, saucisson brioché ou tablier de sapeur. Le menu du midi est le bon plan.","tags":["quenelle","déjeuner"],"lat":45.764372,"lng":4.837706},{"place_id":"ChIJc_459AHr9EcRd0ALc7vrjcI","title":"Le Bouchon des Filles","memo":"Formule unique servie à volonté, façon repas de famille, sur les pentes de la Croix-Rousse. Venez affamé et réservez.","tags":["convivial","dîner"],"lat":45.768673,"lng":4.82936}]},{"name":"Bouchons rive gauche","by":"official","items":[{"place_id":"ChIJ88huwV_q9EcRS_GHcqf1sgQ","title":"Le Val d'Isère","memo":"Bouchon généreux à deux pas des Halles, apprécié des habitués du quartier ; parfait pour un déjeuner copieux.","tags":["copieux","Part-Dieu"],"lat":45.761831,"lng":4.849659},{"place_id":"ChIJV3Wq9xHr9EcRjl_VQWR4KvU","title":"Le Bouchon des Artistes","memo":"Adresse de quartier chaleureuse côté Part-Dieu, loin de l'agitation touristique. Gardez de la place pour la tarte aux pralines.","tags":["quartier","dessert"],"lat":45.758838,"lng":4.848702}]},{"name":"Les Halles Paul Bocuse","by":"official","items":[{"place_id":"ChIJWRzdV_Xq9EcRgE4ciGXEfbM","title":"Chez Antonin","memo":"Huîtres et fruits de mer au comptoir, le grand classique du samedi matin aux Halles avec un verre de blanc.","tags":["huîtres","samedi matin"],"lat":45.763043,"lng":4.850587},{"place_id":"ChIJWRzdV_Xq9EcRLyAYHfxEo1U","title":"Chez Les Gones","memo":"Comptoir des Halles pour goûter la cuisine lyonnaise sur le pouce ; arrivez avant midi pour avoir une place.","tags":["sur le pouce","Halles"],"lat":45.763187,"lng":4.850351},{"place_id":"ChIJ_2g8cyzr9EcRian-iQE25OA","title":"Le Comptoir Paul Bocuse","memo":"Le comptoir de la maison Bocuse au cœur des Halles, pour un plat ou une pâtisserie entre deux emplettes.","tags":["Bocuse","pause gourmande"],"lat":45.763389,"lng":4.850467}]}],"comments":[]}]}$doc$::jsonb);
